import type { RgbValue } from '@/lib/color/types';

export const WCAG_THRESHOLDS = {
  aaNormal: 4.5,
  aaLarge: 3,
  aaaNormal: 7,
  aaaLarge: 4.5,
  // WCAG 1.4.11 (Non-text Contrast) — same numeric threshold as AA Large but a
  // distinct success criterion, covering UI components/graphics, not text.
  uiComponents: 3,
} as const;

function srgbChannelToLinear(c: number): number {
  const cs = c / 255;
  return cs <= 0.03928 ? cs / 12.92 : Math.pow((cs + 0.055) / 1.055, 2.4);
}

export function getRelativeLuminance(rgb: RgbValue): number {
  return (
    0.2126 * srgbChannelToLinear(rgb.r) +
    0.7152 * srgbChannelToLinear(rgb.g) +
    0.0722 * srgbChannelToLinear(rgb.b)
  );
}

export function getContrastRatio(a: RgbValue, b: RgbValue): number {
  const l1 = getRelativeLuminance(a);
  const l2 = getRelativeLuminance(b);
  const lighter = Math.max(l1, l2);
  const darker = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

export interface WcagCompliance {
  aaNormal: boolean;
  aaLarge: boolean;
  aaaNormal: boolean;
  aaaLarge: boolean;
  uiComponents: boolean;
}

export function checkWcagCompliance(ratio: number): WcagCompliance {
  return {
    aaNormal: ratio >= WCAG_THRESHOLDS.aaNormal,
    aaLarge: ratio >= WCAG_THRESHOLDS.aaLarge,
    aaaNormal: ratio >= WCAG_THRESHOLDS.aaaNormal,
    aaaLarge: ratio >= WCAG_THRESHOLDS.aaaLarge,
    uiComponents: ratio >= WCAG_THRESHOLDS.uiComponents,
  };
}

export function getWcagRatingText(ratio: number): string {
  if (ratio >= WCAG_THRESHOLDS.aaaNormal) return 'Excellent';
  if (ratio >= WCAG_THRESHOLDS.aaNormal) return 'Good';
  if (ratio >= WCAG_THRESHOLDS.aaLarge) return 'Acceptable for large text';
  return 'Poor';
}
