import type { FC } from 'react';
import type { WcagCompliance } from '@/lib/contrast/wcag';

interface ComplianceBadgesProps {
  compliance: WcagCompliance;
}

const BADGE_DEFS: { key: keyof WcagCompliance; label: string; requirement: string }[] = [
  { key: 'aaNormal', label: 'AA Normal', requirement: 'Requires 4.5:1' },
  { key: 'aaLarge', label: 'AA Large', requirement: 'Requires 3:1' },
  { key: 'aaaNormal', label: 'AAA Normal', requirement: 'Requires 7:1' },
  { key: 'aaaLarge', label: 'AAA Large', requirement: 'Requires 4.5:1' },
  { key: 'uiComponents', label: 'UI Components', requirement: 'Requires 3:1 · WCAG 1.4.11' },
];

const ComplianceBadges: FC<ComplianceBadgesProps> = ({ compliance }) => {
  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
      {BADGE_DEFS.map(({ key, label, requirement }) => {
        const pass = compliance[key];
        return (
          <div
            key={key}
            className={`rounded-xl p-4 text-center border ${
              pass
                ? 'bg-emerald-500/10 border-emerald-500/40 text-emerald-400'
                : 'bg-destructive/10 border-destructive/40 text-destructive'
            }`}
          >
            <div className="font-semibold text-sm mb-1 text-foreground">{label}</div>
            <div className="text-[11px] opacity-70 mb-2 text-foreground">{requirement}</div>
            <div className="text-sm font-bold">{pass ? '✓ Pass' : '✗ Fail'}</div>
          </div>
        );
      })}
    </div>
  );
};

export default ComplianceBadges;
